import { planVisibility, renderPlan, HIDDEN } from "./plan-visibility.mjs";

const WRONG = "skl-sZFb3KatWY6m", RIGHT = "skl-oBaDO5CceKnr", PEND = "skl-pending";

const baseline = {
  assets: {
